# Arma los HTML de los dos manuales a partir de las capturas (shots/*.png).
# Uso: cd .playwright-mcp && python3 ../docs/manuales/fuente/build.py
import base64
SH = 'shots/'
VERSION = '0.5.0'

def img(n): return 'data:image/png;base64,' + base64.b64encode(open(SH + n + '.png', 'rb').read()).decode()

CSS = '''@page{size:Letter landscape;margin:0}*{box-sizing:border-box}
body{font-family:-apple-system,"Helvetica Neue",Arial,sans-serif;color:#1e293b;margin:0;font-size:11.5pt;line-height:1.4}
.page{page-break-after:always;break-after:page;height:7.3in;overflow:hidden}.page:last-child{page-break-after:auto;break-after:auto}
.cover{display:flex;flex-direction:column;justify-content:center;height:7.3in;background:#101f3d;color:#fff;padding:0 .8in;border-radius:8px}
.cover h1{font-size:44pt;margin:0 0 6px}.cover h2{font-weight:400;font-size:20pt;margin:0 0 30px}.cover p{font-size:12pt;opacity:.9;margin:2px 0}
h1.t{font-size:22pt;margin:0 0 4px;color:#182b52}.sub{color:#475569;margin:0 0 12px}
.cols{display:flex;gap:.3in;align-items:flex-start}.steps{width:3.2in;flex:none}.shot{flex:1}
.shot img{width:100%;border:1px solid #cbd5e1;border-radius:4px;display:block}.shot .cap{font-size:9pt;color:#64748b;margin-top:4px}
ol{padding:0;margin:0;list-style:none;counter-reset:s}ol li{counter-increment:s;position:relative;padding-left:30px;margin-bottom:9px}
ol li:before{content:counter(s);position:absolute;left:0;top:1px;width:22px;height:22px;border-radius:50%;background:#e11d48;color:#fff;font-weight:700;font-size:10.5pt;text-align:center;line-height:22px}
ol.plain{list-style:decimal;padding-left:22px;counter-reset:none}ol.plain li{counter-increment:none;padding-left:4px;margin-bottom:5px}ol.plain li:before{content:none}
.tip{background:#eff6ff;border-left:4px solid #213b6c;padding:7px 10px;margin-top:10px;font-size:10.5pt}
.warn{background:#fff7ed;border-left:4px solid #ea580c;padding:7px 10px;margin-top:10px;font-size:10.5pt}
table{border-collapse:collapse;width:100%;font-size:10pt}th,td{border:1px solid #cbd5e1;padding:4px 7px;text-align:left;vertical-align:top}th{background:#e2e8f0}
code,pre{font-family:Menlo,monospace;font-size:9.5pt;background:#f1f5f9;border-radius:3px}code{padding:1px 4px}pre{padding:8px 10px;margin:6px 0;white-space:pre-wrap}
.two{display:flex;gap:.3in}.two>div{flex:1}h3{margin:10px 0 4px;font-size:12.5pt;color:#182b52}ul{margin:4px 0;padding-left:20px}'''

class Doc:
    def __init__(self, labels): self.parts = []; self.labels = iter(labels)
    def section(self, title, sub, steps, image, cap='', extra=''):
        li = ''.join(f'<li>{s}</li>' for s in steps)
        self.parts.append(f'<section class="page"><h1 class="t">{next(self.labels)}. {title}</h1><p class="sub">{sub}</p><div class="cols"><div class="steps"><ol>{li}</ol>{extra}</div><div class="shot"><img src="{img(image)}"><div class="cap">{cap}</div></div></div></section>')
    def text(self, title, body, numbered=True):
        head = f'{next(self.labels)}. {title}' if numbered else title
        self.parts.append(f'<section class="page"><h1 class="t">{head}</h1>{body}</section>')
    def raw(self, html): self.parts.append(html)
    def save(self, name): open(name, 'w').write(f'<!doctype html><html lang="es"><meta charset="utf-8"><title>{name}</title><style>{CSS}</style><body>{"".join(self.parts)}</body>')

def cover(title, who):
    return f'<section class="page"><div class="cover"><h1>DevPM</h1><h2>{title}</h2><p>{who}</p><p>Versión {VERSION} · Sistema de gestión de proyectos de desarrollo de software</p><p>Las capturas usan los datos de ejemplo de desarrollo.</p></div></section>'

